// /frontend-react/src/components/LanguagePage.js (i18n Enabled - Enhanced Visuals)

import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';
import HeaderBar from './HeaderBar';

const languages = [
    { code: 'en', name: 'English', emoji: '🇬🇧' },
    { code: 'ms', name: 'Bahasa Melayu', emoji: '🇲🇾' },
    { code: 'zh', name: '中文 (Chinese)', emoji: '🇨🇳' },
    { code: 'ta', name: 'தமிழ் (Tamil)', emoji: '🇮🇳' },
];

function LanguagePage({ isEasyMode, goToPage, onMenuClick }) {
    const { t, i18n } = useTranslation(); 
    const currentLang = i18n.resolvedLanguage; 
    
    // 🌟 NEW: State to provide immediate click feedback
    const [lastClickedLang, setLastClickedLang] = useState(null); 

    const handleSelectLanguage = (code) => {
        // Show immediate visual feedback
        setLastClickedLang(code); 
        
        // Change the language globally
        i18n.changeLanguage(code); 
        
        console.log(`Language set to: ${code}`);
        
        // Clear the immediate feedback after a short delay
        setTimeout(() => setLastClickedLang(null), 300); 
    };

    return (
        <div style={{ padding: '0 20px 20px 20px', textAlign: 'center' }}>
            <HeaderBar
                title={t('sidemenu.language')}
                onBackClick={() => goToPage('dashboard')}
                onMenuClick={onMenuClick}
                isEasyMode={isEasyMode}
            />

            <h2 style={{ fontSize: isEasyMode ? '40px' : '30px', margin: '20px 0 10px 0', color: '#333' }}>
                {t('language_page.select_prompt')}
            </h2>
            
            {/* Display Current Language */}
            <p style={{fontSize: isEasyMode ? '24px' : '16px', margin: '0 0 20px 0', fontWeight: 'bold', color: '#1A73E8'}}>
                {t('language_page.current_label')}: {currentLang.toUpperCase()}
            </p>

            {languages.map(lang => {
                const isActive = currentLang === lang.code;
                const isClicked = lastClickedLang === lang.code;
                
                return (
                    <div
                        key={lang.code}
                        onClick={() => handleSelectLanguage(lang.code)}
                        style={{
                            padding: '20px',
                            margin: '15px 0',
                            
                            // 🌟 ENHANCED CSS LOGIC: Use green for active, orange for clicked
                            border: `4px solid ${isActive ? 'green' : (isClicked ? 'orange' : '#ddd')}`,
                            backgroundColor: isActive ? '#E6FBE6' : (isClicked ? '#FFF8E1' : '#fff'),
                            
                            borderRadius: '15px',
                            cursor: 'pointer',
                            textAlign: 'center',
                            transition: 'all 0.2s',
                            boxShadow: isActive ? '0 0 10px rgba(0, 128, 0, 0.4)' : 'none',
                        }}
                    >
                        <span role="img" aria-label={lang.name} style={{ fontSize: isEasyMode ? '60px' : '40px', display: 'block' }}>
                            {lang.emoji}
                        </span>
                        <p style={{ 
                            fontSize: isEasyMode ? '34px' : '22px', 
                            fontWeight: 'bold', 
                            color: isActive ? 'green' : '#333',
                            margin: '5px 0 0 0'
                        }}>
                            {lang.name}
                        </p>
                    </div>
                );
            })}
        </div>
    );
}

export default LanguagePage;
